static const char* b2s(bool b) { return b ? "True" : "False"; }

class ScopeGuard {
    std::function<void()> cleanup_;
    bool active_ = true;
public:
    explicit ScopeGuard(std::function<void()> f) : cleanup_(std::move(f)) {}
    ~ScopeGuard() { if (active_) cleanup_(); }
    void dismiss() { active_ = false; }
    ScopeGuard(const ScopeGuard&) = delete;
    ScopeGuard& operator=(const ScopeGuard&) = delete;
};

int main() {
    bool normalReleased = false;
    {
        ScopeGuard g([&] { normalReleased = true; });
    }
    std::cout << "normal path released=" << b2s(normalReleased) << "\n";

    bool excReleased = false;
    try {
        ScopeGuard g([&] { excReleased = true; });
        throw std::runtime_error("boom");
    } catch (const std::exception& e) {
        std::cout << "caught=" << e.what() << "\n";
    }
    std::cout << "exception path released=" << b2s(excReleased) << "\n";

    bool dismissed = false;
    {
        ScopeGuard g([&] { dismissed = true; });
        g.dismiss();      // 提交：撤销清理
    }
    std::cout << "dismissed guard released=" << b2s(dismissed) << "\n";

    // 多个守卫逆序析构（后构造先释放）
    std::string order;
    {
        ScopeGuard g1([&] { order += "A"; });
        ScopeGuard g2([&] { order += "B"; });
    }
    std::cout << "destruction order=" << order << "\n";
}
